/**
 * Assets used for OS notifications, shared by the service worker's background
 * handler and the page's foreground handler so both look identical.
 *
 * Both are generated by `scripts/generate-notification-assets.py` from the app icon.
 *
 * NOTIFICATION_BADGE must stay a white-on-transparent silhouette: Android renders
 * the status-bar icon from `badge` using only its alpha channel, so an opaque image
 * (such as our app icon) flattens into a plain white box.
 */
export const NOTIFICATION_ICON = '/notification-icon-192x192.png';
export const NOTIFICATION_BADGE = '/notification-badge-96x96.png';
